import{describe,it,expect}from"vitest";import{geologicalFormations,getFilteredFormations}from"../../frontend/volcanoes-geology/volcanoes-geology.js";describe("Volcanoes & Geological Formations Explorer",()=>{it("has minimum 10 formations with complete required fields",()=>{expect(Array.isArray(geologicalFormations)).toBe(!0),expect(geologicalFormations.length).toBeGreaterThanOrEqual(10),geologicalFormations.forEach(e=>{expect(e.id).toBeDefined(),expect(e.name).toBeDefined(),expect(e.location).toBeDefined(),expect(e.type).toBeDefined(),expect(e.description).toBeDefined(),expect(e.rockType).toBeDefined()})}),it("filters by geological category type",()=>{const e=getFilteredFormations("","volcanic");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.type).toBe("volcanic"));const t=getFilteredFormations("","karst");expect(t.length).toBeGreaterThan(0),t.forEach(e=>expect(e.type).toBe("karst"))}),it("covers all four geological categories",()=>{const e=new Set(geologicalFormations.map(e=>e.type));expect(e.has("volcanic")).toBe(!0),expect(e.has("crater")).toBe(!0),expect(e.has("basaltic")).toBe(!0),expect(e.has("karst")).toBe(!0)}),it("searches by name and description",()=>{const e=getFilteredFormations("Lonar");expect(e.length).toBeGreaterThan(0),expect(e[0].name.toLowerCase()).toContain("lonar")})});